package com.platform.learning.web;
import com.platform.family.service.FamilyAccessGuard; import com.platform.learning.repository.ActivityAttemptRepository; import com.platform.learning.repository.EnrollmentRepository; import com.platform.learning.repository.LearningPathRepository; import com.platform.learning.repository.LearningPathItemRepository; import com.platform.streak.service.LearnerStreakService; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
/** TD-25: completions, minutes and path progress are counted in the database, never by loading a child's whole history. */
@RestController @RequestMapping("/api/v1/children/{childId}/progress") public class LearnerProgressController {
 private final FamilyAccessGuard guard; private final com.platform.family.service.ChildAccess childAccess; private final ActivityAttemptRepository attempts; private final LearnerStreakService streaks; private final EnrollmentRepository enrollments; private final LearningPathRepository paths; private final LearningPathItemRepository items;
 public LearnerProgressController(FamilyAccessGuard g,com.platform.family.service.ChildAccess childAccess,ActivityAttemptRepository a,LearnerStreakService s,EnrollmentRepository e,LearningPathRepository p,LearningPathItemRepository i){guard=g;this.childAccess=childAccess;attempts=a;streaks=s;enrollments=e;paths=p;items=i;}
 @GetMapping public Response get(@PathVariable UUID childId,@AuthenticationPrincipal UUID id){childAccess.requireViewer(id,childId);var totals=attempts.completionTotals(childId);long seconds=totals.getSeconds();var s=streaks.get(childId);long total=0,done=0;for(var e:enrollments.findByChildId(childId)){var path=paths.findByEnrollmentId(e.getId());if(path.isPresent()){total+=items.countByLearningPathId(path.get().getId());done+=items.countByLearningPathIdAndStatus(path.get().getId(),com.platform.learning.entity.LearningPathItemStatus.COMPLETED);}}return new Response(childId,totals.getCompleted(),seconds/60,s.getCurrentStreak(),s.getLongestStreak(),done,total);}
 public record Response(UUID childId,long completedActivities,long learningMinutes,int currentStreak,int longestStreak,long completedPathItems,long totalPathItems){}
}
